# hypothesis: A subclass that leaves the abstract property sides unimplemented raises TypeError when instantiated and should be flagged statically, while ABC.register makes an unrelated class pass isinstance without static subtyping.
from abc import ABC, abstractmethod
from typing import reveal_type


class Shape(ABC):
    @property
    @abstractmethod
    def sides(self) -> int: ...

    @abstractmethod
    def area(self) -> float: ...


class Square(Shape):
    def __init__(self, s: float) -> None:
        self.s = s

    @property
    def sides(self) -> int:
        return 4

    def area(self) -> float:
        return self.s * self.s


class Blob(Shape):
    def area(self) -> float:
        return 0.0


class Tile:
    @property
    def sides(self) -> int:
        return 4

    def area(self) -> float:
        return 1.0


Shape.register(Tile)


def make_blob() -> float:
    return Blob().area()  # expect-error


sq = Square(2.0)
reveal_type(sq.sides)
print(sq.sides, sq.area())
print(isinstance(Tile(), Shape), isinstance(sq, Shape))
try:
    make_blob()
except TypeError:
    print('Blob is abstract')
